def rotate_left(lst, n):
    if not lst:
        return []
    n = n % len(lst)
    return lst[n:] + lst[:n]


def interleave(a, b):
    result = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            result.append(a[i])
        if i < len(b):
            result.append(b[i])
    return result


def chunk(lst, size):
    return [lst[i:i + size] for i in range(0, len(lst), size)]
